#!/bin/bash
# A simple script to copy example config files to the user's home directory

CFG="${HOME}/.config/solarsystemsim"
RSC=./resources

echo "Setting up config directory..."

# First ensure that the config directory exists
mkdir -p "${CFG}"

echo "Copying example config files..."

# Copy the example main setup file
# This will have to be renamed to setup.properties
cp "${RSC}/example_setup.properties" "${CFG}/example_setup.properties"

# Copy example system setups, including the autogenerated one
cp "${RSC}/example_system.properties" "${CFG}/example_system.properties"
cp "${RSC}/solar_system.properties" "${CFG}/solar_system.properties"
cp "${RSC}/out/random_system.properties" "${CFG}/random_system.properties"

echo "Finished configuring Solar System Simulator!"
